import{_ as i,o as t,c as a,a2 as r}from"./chunks/framework.Cd7uensT.js";const c=JSON.parse('{"title":"版本更新","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1784265931000}'),o={name:"changelog.md"};function e(n,l,s,g,h,d){return t(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="版本更新" tabindex="-1">版本更新 <a class="header-anchor" href="#版本更新" aria-label="Permalink to &quot;版本更新&quot;">​</a></h1><h2 id="文档站点-v1-0-0-2025-06-16" tabindex="-1">文档站点 v1.0.0（2025-06-16） <a class="header-anchor" href="#文档站点-v1-0-0-2025-06-16" aria-label="Permalink to &quot;文档站点 v1.0.0（2025-06-16）&quot;">​</a></h2><blockquote><p>对应项目代码版本 [v2.1.0]</p></blockquote><ul><li><strong>初始文档站点发布</strong></li><li>基于 VitePress 构建，部署于 GitHub Pages（<a href="https://gituib.github.io/idc_assest-docs/" target="_blank" rel="noreferrer">https://gituib.github.io/idc_assest-docs/</a>）</li><li>完整的使用指南：涵盖机房管理、设备管理、耗材管理、工单管理等所有功能模块的详细说明</li><li>开发手册：包含系统架构、前端架构、后端架构、数据模型等设计文档</li><li>部署运维指南：Docker 部署、手动部署、环境配置说明</li><li>API 文档：后端接口参考文档</li><li>版本更新记录与 FAQ 常见问题</li></ul><h2 id="项目代码" tabindex="-1">项目代码 <a class="header-anchor" href="#项目代码" aria-label="Permalink to &quot;项目代码&quot;">​</a></h2><h3 id="v2-2-3-2026-07-17" tabindex="-1">v2.2.3（2026-07-17） <a class="header-anchor" href="#v2-2-3-2026-07-17" aria-label="Permalink to &quot;v2.2.3（2026-07-17）&quot;">​</a></h3><ul><li><strong>3D 可视化优化</strong>：优化3D机柜设备颜色辨识度（服务器深石墨灰、交换机中灰偏蓝、防火墙深灰红调、存储深炭灰），增加设备上下银色边框条分隔相邻设备</li><li><strong>3D 结构增强</strong>：机柜内部两侧增加前安装轨，强化结构真实感与层次感</li><li><strong>3D 闪烁修复</strong>：修复4处 Z-fighting 深度冲突（侧板与立柱、前安装轨与前面板等），优化 OrbitControls 中键平移与全屏功能</li><li><strong>3D 页面布局重构</strong>：顶部 Header 改为浅色玻璃态适配 light theme，右侧 Rack Info 面板浅色玻璃态重构，新增底部 KPI 快捷栏</li><li><strong>3D 交互修复</strong>：修复 Header 按钮点击无响应、左键旋转失效等问题，规范化 Z-Index 层级体系</li><li><strong>仪表盘修复</strong>：修复 NavigationGrid 响应式布局、QuickStats hover 动画、SystemInfo 伪造数据、AnimatedCounter 动画重置、DeviceTrendChart 空数组异常等5个 P0 级问题</li><li><strong>端口管理修复</strong>：修复交换机子页签误显示防火墙/路由器/存储设备的问题</li><li><strong>端口管理增强</strong>：支持自定义设备类型进入端口管理，设备图标按类型区分背景色，新增「其他」Tab 展示自定义类型设备</li><li><strong>空闲设备优化</strong>：状态字段过滤 idle 选项</li></ul><h3 id="v2-2-2-2026-07-16" tabindex="-1">v2.2.2（2026-07-16） <a class="header-anchor" href="#v2-2-2-2026-07-16" aria-label="Permalink to &quot;v2.2.2（2026-07-16）&quot;">​</a></h3><ul><li><strong>分页配置扩展</strong>：前端分页可选条数扩展至 100/200/500/1000</li><li><strong>设备表单修复</strong>：修复设备表单字段重复渲染和残留值问题</li></ul><h3 id="v2-2-1-2026-07-11" tabindex="-1">v2.2.1（2026-07-11） <a class="header-anchor" href="#v2-2-1-2026-07-11" aria-label="Permalink to &quot;v2.2.1（2026-07-11）&quot;">​</a></h3><ul><li><strong>批量维保更新</strong>：新增批量更新设备维保信息功能，包含前后端完整实现</li><li><strong>端口选项集中管理</strong>：新增端口选项接口与集中管理 hook，统一维护端口/线缆类型数据</li><li><strong>端口/线缆类型扩展</strong>：扩展端口类型、线缆类型枚举值，支持更多硬件规格</li><li><strong>网卡编辑功能</strong>：新增网卡编辑功能，完善设备端口管理流程</li><li><strong>3D 机柜优化</strong>：优化3D机柜U位渲染逻辑，修复机柜使用率计算问题，重构3D材质与模型渲染</li><li><strong>3D 交互修复</strong>：修复3D可视化交互问题，优化背板渲染逻辑</li></ul><h3 id="v2-2-0-2026-07-03" tabindex="-1">v2.2.0（2026-07-03） <a class="header-anchor" href="#v2-2-0-2026-07-03" aria-label="Permalink to &quot;v2.2.0（2026-07-03）&quot;">​</a></h3><ul><li><strong>端口管理重构</strong>：重构端口管理页面，新增端口批量操作（批量编辑、批量清理）、分组预览功能，提升端口运维效率</li><li><strong>线缆管理优化</strong>：优化线缆管理流程，增强端口跳线引导体验，支持更直观的连线操作指引</li><li><strong>空闲设备管理功能</strong>：新增空闲设备列表与详情展示页面，支持按资产编号、设备名称、设备型号搜索筛选</li><li><strong>空闲设备字段优化</strong>：移除空闲设备表单中的资产状态和入库日期字段，优化数据录入体验</li><li><strong>用户管理列表优化</strong>：修复用户管理列表分页超出一页时系统设置 Tab 切换失效的问题</li><li><strong>盘点管理详情优化</strong>：修复盘点完成状态回显显示问题，优化部分页面字段展示</li><li><strong>耗材管理优化</strong>：修复耗材入库数量显示异常的问题</li><li><strong>无数据页面优化</strong>：优化空闲设备页面、库位页面、工单详情页的无数据展示提示</li><li><strong>系统稳定性提升</strong>：修复多处前端逻辑异常和状态管理问题</li></ul><h3 id="v2-1-1-2026-06-16" tabindex="-1">v2.1.1（2026-06-16） <a class="header-anchor" href="#v2-1-1-2026-06-16" aria-label="Permalink to &quot;v2.1.1（2026-06-16）&quot;">​</a></h3><ul><li><strong>端口管理优化</strong>：新增按设备分组的端口查询 API，修复端口过多时部分设备不显示的分页问题</li><li><strong>前端端口页面重构</strong>：改为设备维度分页，移除旧的端口级分页逻辑，统一端口名称自然排序</li></ul><h3 id="v2-1-0" tabindex="-1">v2.1.0 <a class="header-anchor" href="#v2-1-0" aria-label="Permalink to &quot;v2.1.0&quot;">​</a></h3><ul><li>优化系统设置页面</li><li>增强设备字段管理功能</li><li>改进3D可视化性能</li></ul><h3 id="v2-0-0" tabindex="-1">v2.0.0 <a class="header-anchor" href="#v2-0-0" aria-label="Permalink to &quot;v2.0.0&quot;">​</a></h3><ul><li><strong>重大更新：重构前端架构</strong>，采用 React + Vite 构建，提升开发效率和运行性能</li><li>引入 Three.js + @react-three/fiber，实现 3D 机柜可视化展示</li><li>新增工单管理系统：完整的工单流转、故障分类与优先级管理</li><li>新增耗材库存管理：入库出库、安全库存预警、SN 序列号追踪</li><li>新增资产盘点功能：盘点计划、暂存设备、盘盈处理</li><li>重构备份管理模块，支持更灵活的数据备份与恢复</li><li>增强 RBAC 权限控制，支持更细粒度的角色权限配置</li><li>升级 UI 组件库至 Ant Design 5</li></ul><h3 id="v1-0-0" tabindex="-1">v1.0.0 <a class="header-anchor" href="#v1-0-0" aria-label="Permalink to &quot;v1.0.0&quot;">​</a></h3><ul><li>初始版本发布</li><li>基本的设备 CRUD 功能</li><li>机房与机柜管理</li><li>简单的统计看板</li></ul>',21)])])}const v=i(o,[["render",e]]);export{c as __pageData,v as default};
